{"sql":"CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id INTEGER,
    target_inventory_id INTEGER,
    part_to_transfer_num VARCHAR,
    color_to_transfer_id INTEGER,
    quantity_to_transfer INTEGER,
    transfer_reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT AS $$
DECLARE
    v_source_qty INTEGER;
    v_target_qty INTEGER;
    v_message TEXT;
BEGIN
    -- Begin transaction block implicitly by function execution

    -- Prevent self-transfer
    IF source_inventory_id = target_inventory_id THEN
        RAISE EXCEPTION 'Source and target inventory cannot be the same for transfer';
    END IF;

    -- Lock source and target inventories
    PERFORM 1 FROM lego_inventories WHERE inventory_id = source_inventory_id FOR UPDATE;
    PERFORM 1 FROM lego_inventories WHERE inventory_id = target_inventory_id FOR UPDATE;

    -- Basic existence checks
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE inventory_id = source_inventory_id) THEN
        RAISE EXCEPTION 'Source inventory % does not exist', source_inventory_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE inventory_id = target_inventory_id) THEN
        RAISE EXCEPTION 'Target inventory % does not exist', target_inventory_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num) THEN
        RAISE EXCEPTION 'Part % does not exist', part_to_transfer_num;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lego_colors WHERE color_id = color_to_transfer_id) THEN
        RAISE EXCEPTION 'Color ID % does not exist', color_to_transfer_id;
    END IF;

    -- Business rule checks
    IF quantity_to_transfer < 1 OR quantity_to_transfer > 500 THEN
        RAISE EXCEPTION 'Transfer quantity % is out of valid range (1 to 500)', quantity_to_transfer;
    END IF;

    -- Check sufficient quantity in source non-spare row
    SELECT quantity INTO v_source_qty FROM lego_inventory_parts
    WHERE inventory_id = source_inventory_id
      AND part_num = part_to_transfer_num
      AND color_id = color_to_transfer_id
      AND is_spare = false
    FOR UPDATE;

    IF v_source_qty IS NULL THEN
        RAISE EXCEPTION 'No non-spare inventory for part % color % in source inventory %', part_to_transfer_num, color_to_transfer_id, source_inventory_id;
    ELSIF v_source_qty < quantity_to_transfer THEN
        RAISE EXCEPTION 'Insufficient quantity in source inventory % for part % color %: have %, need %', source_inventory_id, part_to_transfer_num, color_to_transfer_id, v_source_qty, quantity_to_transfer;
    END IF;

    -- Deduct from source
    IF v_source_qty = quantity_to_transfer THEN
        DELETE FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
          AND is_spare = false;
    ELSE
        UPDATE lego_inventory_parts
        SET quantity = quantity - quantity_to_transfer
        WHERE inventory_id = source_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
          AND is_spare = false;
    END IF;

    -- Add to target
    SELECT quantity INTO v_target_qty FROM lego_inventory_parts
    WHERE inventory_id = target_inventory_id
      AND part_num = part_to_transfer_num
      AND color_id = color_to_transfer_id
      AND is_spare = false
    FOR UPDATE;

    IF v_target_qty IS NULL THEN
        INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, false);
    ELSE
        UPDATE lego_inventory_parts
        SET quantity = quantity + quantity_to_transfer
        WHERE inventory_id = target_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
          AND is_spare = false;
    END IF;

    -- Log successful transfer
    INSERT INTO inventory_transfer_log(
        source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'success', NULL
    );

    -- Success message
    v_message := FORMAT('Successfully transferred % parts (%s, color_id: %s) from inventory % to inventory %. Reason: %s',
        quantity_to_transfer, part_to_transfer_num, color_to_transfer_id, source_inventory_id, target_inventory_id, transfer_reason);

    RETURN v_message;

EXCEPTION
    WHEN OTHERS THEN
        -- Log failed transfer with error message
        INSERT INTO inventory_transfer_log(
            source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', SQLERRM
        );
        RAISE;
END;
$$ LANGUAGE plpgsql;"}
